mod names_list;
use names_list::NAMES;
use std::io::BufRead;
fn variant(v: u32, p: (u8,u8,u8), order: &[usize]) -> &'static str {
    let (r,g,b) = (p.0 as f64, p.1 as f64, p.2 as f64);
