            d.sort_unstable_by(|a,b| a.0.cmp(&b.0)); NAMES[d[0].1].0 }
        1 => { // f32 sqrt, sort_unstable partial_cmp
            let mut d: Vec<(f32, usize)> = order.iter().map(|&i| { let c=NAMES[i]; let dr=p.0 as f32-c.1 as f32; let dg=p.1 as f32-c.2 as f32; let db=p.2 as f32-c.3 as f32; ((dr*dr+dg*dg+db*db).sqrt(), i)}).collect();
            d.sort_unstable_by(|a,b| a.0.partial_cmp(&b.0).unwrap()); NAMES[d[0].1].0 }
        2 => { // f32 normalized
            let mut d: Vec<(f32, usize)> = order.iter().map(|&i| { let c=NAMES[i]; let dr=p.0 as f32/255.0-c.1 as f32/255.0; let dg=p.1 as f32/255.0-c.2 as f32/255.0; let db=p.2 as f32/255.0-c.3 as f32/255.0; ((dr*dr+dg*dg+db*db).sqrt(), i)}).collect();
            d.sort_unstable_by(|a,b| a.0.partial_cmp(&b.0).unwrap()); NAMES[d[0].1].0 }
        3 => { // f64 normalized
            let mut d: Vec<(f64, usize)> = order.iter().map(|&i| { let c=NAMES[i]; let dr=r/255.0-c.1 as f64/255.0; let dg=g/255.0-c.2 as f64/255.0; let db=b/255.0-c.3 as f64/255.0; ((dr*dr+dg*dg+db*db).sqrt(), i)}).collect();
            d.sort_unstable_by(|a,b| a.0.partial_cmp(&b.0).unwrap()); NAMES[d[0].1].0 }
        _ => unreachable!()
    }
}
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let f = std::fs::File::open(&args[1]).unwrap();
    let mut data = vec![];
    for line in std::io::BufReader::new(f).lines() {
