/// Tie-break table: sorted runs of (rgb24 start, choice index). For colours
/// that are equally close to several named colours, the entry covering the
/// colour tells which of the (alphabetically ordered) candidates is chosen.
static TIE_RUNS: &[u8] = include_bytes!("tie_runs.bin");

const NAMER_SRC: &str =
    "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/colornamer-0.1.0/src/color.rs";

fn tie_choice(v: u32) -> usize {
    let n = TIE_RUNS.len() / 4;
    let key = |i: usize| -> u32 {
        let b = &TIE_RUNS[i * 4..i * 4 + 3];
        ((b[0] as u32) << 16) | ((b[1] as u32) << 8) | (b[2] as u32)
    };
    // find last run with start <= v
    let mut lo = 0usize;
    let mut hi = n;
    while lo < hi {
        let mid = (lo + hi) / 2;
        if key(mid) <= v {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if lo == 0 {
        return 0;
    }
    TIE_RUNS[(lo - 1) * 4 + 3] as usize
}

fn parse_hex(hex: &str) -> (u8, u8, u8) {
    let body = hex.strip_prefix('#').unwrap_or(hex);
    let chars: Vec<char> = body.chars().collect();
    if chars.len() < 6 {
        fail(&format!("{}:46:9", NAMER_SRC), &format!("got invalid hex string: {:?}", hex));
    }
    let mut vals = [0u8; 3];
    for (i, v) in vals.iter_mut().enumerate() {
        let hi = chars[i * 2].to_digit(16);
        let lo = chars[i * 2 + 1].to_digit(16);
        match (hi, lo) {
            (Some(h), Some(l)) => *v = (h * 16 + l) as u8,
            _ => fail(&format!("{}:53:13", NAMER_SRC), &format!("got invalid hex string: {:?}", hex)),
        }
    }
    (vals[0], vals[1], vals[2])
}

/// Returns the name of the closest HTML colour for the given hex string.
pub fn name_hex_color(hex: &str) -> String {
    let (r, g, b) = parse_hex(hex);
    let mut best = i32::MAX;
    let mut tied: Vec<usize> = Vec::new();
    for (i, c) in COLORS.iter().enumerate() {
        let dr = r as i32 - c.1 as i32;
        let dg = g as i32 - c.2 as i32;
        let db = b as i32 - c.3 as i32;
        let d = dr * dr + dg * dg + db * db;
        if d < best {
            best = d;
            tied.clear();
            tied.push(i);
        } else if d == best {
            tied.push(i);
        }
    }
    let idx = if tied.len() == 1 {
        tied[0]
    } else {
        let v = ((r as u32) << 16) | ((g as u32) << 8) | (b as u32);
        let choice = tie_choice(v);
        tied[if choice < tied.len() { choice } else { 0 }]
    };
    COLORS[idx].0.to_string()
}
