//! Applies a theme to an i3 config, line by line.

use crate::theme::{BarColors, ColorGroup, Theme};
use crate::{fail_none, fail_unwrap_err, oob};
use std::io::{BufRead, Write};

pub enum Out {
    Stdout(std::io::Stdout),
    File(std::fs::File),
}

impl Out {
    fn w(&mut self, s: &str) {
        let res = match self {
            Out::Stdout(o) => o.write_all(s.as_bytes()),
            Out::File(f) => f.write_all(s.as_bytes()),
        };
        if let Err(e) = res {
            fail_unwrap_err("src/writer.rs:481:29", &e);
        }
    }
}

fn leading_ws(line: &str) -> &str {
    let trimmed = line.trim_start();
    &line[..line.len() - trimmed.len()]
}

fn part<'a>(parts: &[&'a str], idx: usize, loc: &str) -> &'a str {
    match parts.get(idx) {
        Some(p) => p,
        None => oob(loc, parts.len(), idx),
    }
}

const BAR_KEYS: [&str; 7] = [
    "separator",
    "background",
    "statusline",
    "focused_workspace",
    "active_workspace",
    "inactive_workspace",
    "urgent_workspace",
];

fn bar_group<'a>(bc: &'a BarColors, key: &str) -> &'a Option<ColorGroup> {
    match key {
        "focused_workspace" => &bc.focused_workspace,
        "active_workspace" => &bc.active_workspace,
        "inactive_workspace" => &bc.inactive_workspace,
        _ => &bc.urgent_workspace,
    }
}

fn bar_simple<'a>(bc: &'a BarColors, key: &str) -> &'a Option<String> {
    match key {
        "separator" => &bc.separator,
        "background" => &bc.background,
        _ => &bc.statusline,
    }
}

/// Writes the colour entries that were not present in a colors block.
fn write_missing_bar(out: &mut Out, bc: &BarColors, seen: &[bool; 7], indent: &str) {
    for (i, key) in BAR_KEYS.iter().enumerate() {
        if seen[i] {
            continue;
        }
        if i < 3 {
            if let Some(v) = bar_simple(bc, key) {
                out.w(&format!("{}{} {}\n", indent, key, v));
            }
        } else if let Some(g) = bar_group(bc, key) {
            if let (Some(b), Some(bg), Some(t)) = (&g.border, &g.background, &g.text) {
                out.w(&format!("{}{} {} {} {} \n", indent, key, b, bg, t));
            }
        }
    }
}

const CLIENT_KEYS: [&str; 4] = ["focused", "focused_inactive", "unfocused", "urgent"];

