//! Command line handling.

use std::collections::BTreeMap;

pub struct Matches {
    pub theme: Option<String>,
    pub config: Option<String>,
    pub output: Option<String>,
    pub to_theme: String,
    pub to_theme_occurs: usize,
    pub save: bool,
    pub reload: bool,
    pub list_all: bool,
}

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Flag,
    Opt,
}

struct ArgDef {
    name: &'static str,
    short: char,
    long: &'static str,
    kind: Kind,
}

const ARGS: &[ArgDef] = &[
    ArgDef { name: "list-all", short: 'l', long: "list-all", kind: Kind::Flag },
    ArgDef { name: "reload", short: 'r', long: "reload", kind: Kind::Flag },
    ArgDef { name: "save", short: 's', long: "save", kind: Kind::Flag },
    ArgDef { name: "help", short: 'h', long: "help", kind: Kind::Flag },
    ArgDef { name: "version", short: 'V', long: "version", kind: Kind::Flag },
    ArgDef { name: "config", short: 'c', long: "config", kind: Kind::Opt },
    ArgDef { name: "output", short: 'o', long: "output", kind: Kind::Opt },
    ArgDef { name: "to-theme", short: 't', long: "to-theme", kind: Kind::Opt },
];

fn find_long(l: &str) -> Option<&'static ArgDef> {
    ARGS.iter().find(|a| a.long == l)
}

fn find_short(c: char) -> Option<&'static ArgDef> {
    ARGS.iter().find(|a| a.short == c)
}

fn find_name(n: &str) -> &'static ArgDef {
    ARGS.iter().find(|a| a.name == n).unwrap()
}

fn display(a: &ArgDef) -> String {
    match a.kind {
        Kind::Flag => format!("--{}", a.long),
        Kind::Opt => format!("--{} <file>", a.long),
    }
}

pub struct Ctx {
    pub bin_name: String,
    pub app_title: String,
}

impl Ctx {
    pub fn from_argv0(argv0: Option<&std::ffi::OsStr>) -> Ctx {
        let mut bin_name: Option<String> = None;
        if let Some(a) = argv0 {
            let p = std::path::Path::new(a);
            if let Some(f) = p.file_name() {
                if let Some(s) = f.to_str() {
                    bin_name = Some(s.to_owned());
                }
            }
        }
        let app_title = match &bin_name {
            Some(b) if b.contains(' ') => b.replace(' ', "-"),
            _ => "i3-style".to_string(),
        };
        Ctx { bin_name: bin_name.unwrap_or_else(|| "i3-style".to_string()), app_title }
    }

    pub fn general_usage(&self) -> String {
        format!("{} [FLAGS] [OPTIONS] [theme]", self.bin_name)
    }

    fn help(&self) -> String {
        let mut s = String::new();
        s.push_str(&format!("{} 1.0\n", self.app_title));
        s.push_str("Make your i3 config a bit more stylish\n\n");
        s.push_str("USAGE:\n");
        s.push_str(&format!("    {}\n\n", self.general_usage()));
        s.push_str("FLAGS:\n");
        s.push_str("    -h, --help        Prints help information\n");
        s.push_str("    -l, --list-all    Print a list of all available themes\n");
        s.push_str("    -r, --reload      Apply the theme by reloading the config\n");
        s.push_str("    -s, --save        Set the output file to the path of the input file\n");
        s.push_str("    -V, --version     Prints version information\n\n");
        s.push_str("OPTIONS:\n");
        s.push_str("    -c, --config <file>      The config file the theme should be applied to. Defaults to the default i3 location.\n");
        s.push_str("    -o, --output <file>      Apply the theme, attempt to validate the result, and write it to <file>\n");
        s.push_str("    -t, --to-theme <file>    Prints an i3-style theme based on the given config suitable for sharing with others\n");
        s.push_str("                             [default: ]\n\n");
        s.push_str("ARGS:\n");
        s.push_str("    <theme>    The theme to use\n");
        s
    }
}

struct State {
    occurs: BTreeMap<&'static str, usize>,
    vals: BTreeMap<&'static str, Vec<String>>,
}

impl State {
    fn used_usage(&self, ctx: &Ctx, extra: Option<&'static str>) -> String {
        let mut names: Vec<&str> = self.occurs.keys().copied().collect();
        if let Some(e) = extra {
            names.push(e);
        }
        names.sort();
        names.dedup();
        if names.is_empty() {
            return ctx.general_usage();
        }
        let mut s = ctx.bin_name.clone();
        for n in names {
            s.push(' ');
            s.push_str(&display(find_name(n)));
        }
        s
    }

    fn touch(&mut self, name: &'static str) {
        *self.occurs.entry(name).or_insert(0) += 1;
    }
}

fn exit_error(msg: &str, usage: &str) -> ! {
    eprint!("error: {}\n\nUSAGE:\n    {}\n\nFor more information try --help\n", msg, usage);
    std::process::exit(1);
}

fn jaro(a: &str, b: &str) -> f64 {
    if a == b {
        return 1.0;
    }
    let a_len = a.chars().count();
    let b_len = b.chars().count();
    if a_len == 0 || b_len == 0 || (a_len == 1 && b_len == 1) {
        return 0.0;
    }
    let search_range = (std::cmp::max(a_len, b_len) / 2) - 1;
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0;
    let mut transpositions = 0.0;
    let mut b_match_index = 0;
    for (i, a_char) in a.chars().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = std::cmp::min(b_len - 1, i + search_range);
        for (j, b_char) in b.chars().enumerate().take(max_bound + 1) {
            if min_bound <= j && a_char == b_char && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
}

