{"command":"cd /workspace/src && cat > main.rs <<'EOF'
//! i3-style: apply colour themes to an i3 config.

mod builtin;
mod cli;
mod namer;
mod theme;
mod writer;
mod yaml;

use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::Command;

/// Reports an unrecoverable internal error in the same style as a Rust panic
/// and terminates the process.
pub fn fail(location: &str, msg: &str) -> ! {
    let _ = std::io::stdout().flush();
    let mut err = std::io::stderr();
    let _ = write!(
        err,
        "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        std::process::id(),
        location,
        msg
    );
    std::process::exit(101);
}

pub fn fail_unwrap_err<E: std::fmt::Debug>(location: &str, e: &E) -> ! {
    fail(location, &format!("called `Result::unwrap()` on an `Err` value: {:?}", e))
}

pub fn fail_none(location: &str) -> ! {
    fail(location, "called `Option::unwrap()` on a `None` value")
}

pub fn oob(location: &str, len: usize, idx: usize) -> ! {
    fail(location, &format!("index out of bounds: the len is {} but the index is {}", len, idx))
}

fn find_default_config() -> Option<String> {
    let home = match std::env::var("HOME") {
        Ok(h) => h,
        Err(e) => fail_unwrap_err("src/main.rs:47:46", &e),
    };
    let candidates = [format!("{}/.i3/config", home), format!("{}/.config/i3/config", home)];
    candidates.into_iter().find(|p| Path::new(p).exists())
}

fn resolve_config(given: Option<&str>) -> String {
    match given {
        Some(c) => c.to_string(),
        None => match find_default_config() {
            Some(c) => c,
            None => {
                eprintln!("Could not find i3 config");
                std::process::exit(1);
            }
        },
    }
}

fn validate_config(path: &str) {
    match Command::new("i3").arg("-C").arg("-c").arg(path).output() {
        Err(e) => {
            eprintln!(
                "Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}",
                path, e
            );
            std::process::exit(1);
        }
        Ok(out) => {
            if !out.status.success() {
                eprintln!("Could not validate config.\nUse `i3 -C -c {}` to see validation errors.", path);
                std::process::exit(1);
            }
        }
    }
}

fn load_theme(name: &str) -> theme::Theme {
    if let Some(t) = builtin::builtin(name) {
        return t;
    }
    let contents = match std::fs::read_to_string(name) {
        Ok(c) => c,
        Err(e) => {
            eprintln!(
                "Could not open theme: {} - {}\n Use `i3-style --list-all` to see the available themes.",
                name, e
            );
            std::process::exit(1);
        }
    };
    let docs = match yaml::load_from_str(&contents) {
        Ok(d) => d,
        Err(e) => fail("src/main.rs:128:54", &format!("Could not parse yaml for theme: {:?}", e)),
    };
    if docs.is_empty() {
        oob("src/main.rs:129:20", 0, 0);
    }
    theme::Theme::from_yaml(&docs[0])
}

fn list_themes() {
    println!();
    println!("Available themes:");
    println!();
    let width = builtin::THEMES.iter().map(|(n, _)| n.len()).max().unwrap_or(0);
    for (name, desc) in builtin::THEMES {
        println!("  {:<width$} - {}", name, desc, width = width);
    }
}

fn tmp_dir() -> PathBuf {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default();
    let n = now.as_secs() + now.subsec_millis() as u64;
    let dir = std::env::temp_dir().join("i3-style").join(n.to_string());
    if let Err(e) = std::fs::create_dir_all(&dir) {
        fail("src/main.rs:42:39", &format!("Could not create temporary directory: {:?}", e));
    }
    dir
}

fn reload() {
    if let Err(e) = Command::new("i3-msg").arg("reload").output() {
        eprintln!("Could not reload config with i3-msg: {}", e);
        std::process::exit(1);
    }
}

